﻿using UnityEngine;
using System.Collections;
using System;
using UnityEngine.UI;
using System.Linq;

public class Calculator : MonoBehaviour
{

	public Text _input;
	public Text _result;

	private float _x, _y;
	private string _op;
	private bool sqrt = false;

	//Initialization
	private void Start()
	{
		ResetAll();
	}

	//Reset fields and member variables
	private void ResetAll()
	{
		ClearField();
		_x = 0.0f;
		_y = 0.0f;
		_op = "";
	}

	//Handle values coming from button clicks
	public void SetInputValue(string s)
	{
		//Clear fields if _input contains letters
		if (_input.text.ToString().Any(x => char.IsLetter(x)))
		{
			ResetAll();
		}

		//Handles button input values
		switch (s)
		{
			case "+":
			case "-":
			case "/":
			case "*":
			case "=":
			case "^":
			case "√":
				Calculate(s);
				break;
			case "ce":
				ClearLastInput();
				break;
			case "c":
				ResetAll();
				break;
			case "del":
				DeleteLastCharacter();
				break;
			default:
				AddCharacter(s);
				break;
		}
	}

	//Prepare values before the calculation
	private void Calculate(string s)
	{
		//If result field is empty
		if (_result.text == "" && s != "=" && s != "√")
		{
			_x = Convert.ToSingle(_input.text);
			_op = s;
			_result.text = _input.text + " " + s;
			_input.text = "0";
			return;
		}
		else if (_result.text == "" && s != "=" && s == "√")
		{
			sqrt = true;
			_x = Convert.ToSingle(_input.text);
			_op = s;
			_result.text = s + " " + _input.text;
			_input.text = "";
			return;
		}

		//Handles division by 0
		if (_op == "/" && _input.text == "0")
		{
			ResetAll();
			_input.text = "Cannot divide by zero";
			return;
		}

		//Calculates float result if its not square root
		if (!sqrt)
        {
			_y = Convert.ToSingle(_input.text);
		}

		//Checks if "=" is pressed to calculate, and checks if its sqrt
		if (s == "=" && !sqrt)
		{
			ClearField();
			_input.text = CalculatePair(_x, _y, _op).ToString();
			sqrt = false;
		}
		//If "=" is pressed and its sqrt, it will run CalculateSqrt()
		else if (s == "=" && sqrt)
        {
			ClearField();
			_input.text = CalculateSqrt(_x).ToString();
			sqrt = false;
		}
		else
		{
			_x = Convert.ToSingle(CalculatePair(_x, _y, _op));
			_result.text = _x.ToString() + " " + s;
			_op = s;
			_input.text = "0";
			sqrt = false;
		}
	}

	//Return the result of an operation between 2 floats
	public static float CalculatePair(float x, float y, string op)
	{
		float result = 0.0f;

		switch (op)
		{
			case "+":
				result = x + y;
				break;
			case "-":
				result = x - y;
				break;
			case "*":
				result = x * y;
				break;
			case "/":
				result = x / y;
				break;
			case "^":
				result = Mathf.Pow(x, y);
				break;
		}

		return result;
	}

	//Calculates sqrt
	public static float CalculateSqrt(float x)
	{
		float result = Mathf.Sqrt(x);

		return result;
	}

	//Add character input to input text string
	private void AddCharacter(string s)
	{
		//Add only one decimal point
		if (s == ".")
		{
			if (!_input.text.ToString().Contains("."))
			{
				_input.text += s;
			}
			//Remove 0 in front of number
		}
		else if (_input.text == "0")
		{
			_input.text = s;
			//Concatenate the input string
		}
		else
		{
			_input.text += s;
		}
	}

	//Delete last character of the input string when CE is pressed
	private void DeleteLastCharacter()
	{
		_input.text = _input.text.ToString().Remove(_input.text.Length - 1);

		if (_input.text == "")
		{
			_input.text = "0";
		}
	}

	//Reset input field
	private void ClearLastInput()
	{
		_input.text = "0";
	}

	//Clear all fields when C is pressed
	private void ClearField()
	{
		_result.text = "";
		_input.text = "0";
	}
}

