                    if (result[j + 1] + number2 >= 10) {
                        result[j + 1] = (result[j + 1] + number2) % 10;
                        if (result[j] == ' ') {
                            result[j] = 1;
                        }
                        else {
                            result[j] += 1;
                        }
                    }
                    else {
                        result[j + 1] += number2;
                    }

                }
            }
            //когда второе число меньше первого получение цифр 1 9 (пример 1982 + 80)
            else if (j < 0 && i >= 0) {
                number1 = translate_to_int(num1[i]);
                number2 = 0;
                if (result[i + 1] == ' ') {
                    result[i + 1] = number1;
                }
